import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/workspace.md","filePath":"concepts/workspace.md","lastUpdated":1784904021000}'),n={name:"concepts/workspace.md"};function o(p,a,c,h,l,d){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h1><p>The workspace is the directory where swag2mcp stores all its data — config, cached specs, local spec files, saved responses, and auth scripts.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/                          # Workspace root (default)</span></span>
<span class="line"><span>├── swag2mcp.yaml                     # Configuration file</span></span>
<span class="line"><span>├── cache/                            # Cached remote spec files</span></span>
<span class="line"><span>│   ├── a1b2c3d4e5f6...spec          # Cached spec content</span></span>
<span class="line"><span>│   └── a1b2c3d4e5f6...meta          # Cache metadata (JSON)</span></span>
<span class="line"><span>├── specs/                            # Local spec files</span></span>
<span class="line"><span>│   └── my-api.yaml</span></span>
<span class="line"><span>├── responses/                        # Saved API responses (large responses)</span></span>
<span class="line"><span>│   ├── meteo-get-forecast-abc123.json</span></span>
<span class="line"><span>│   └── response-fragment-def456.json</span></span>
<span class="line"><span>└── auth_scripts/                     # Authentication scripts</span></span>
<span class="line"><span>    ├── meteo.sh                      # Unix shell script</span></span>
<span class="line"><span>    └── meteo.bat                     # Windows batch script</span></span></code></pre></div><h2 id="default-path" tabindex="-1">Default Path <a class="header-anchor" href="#default-path" aria-label="Permalink to &quot;Default Path&quot;">​</a></h2><ul><li><strong>Linux/macOS</strong>: <code>~/.swag2mcp/</code></li><li><strong>Windows</strong>: <code>%USERPROFILE%\\.swag2mcp\\</code></li></ul><h2 id="custom-path" tabindex="-1">Custom Path <a class="header-anchor" href="#custom-path" aria-label="Permalink to &quot;Custom Path&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-workspace</span></span></code></pre></div><h2 id="directories" tabindex="-1">Directories <a class="header-anchor" href="#directories" aria-label="Permalink to &quot;Directories&quot;">​</a></h2><h3 id="cache" tabindex="-1">cache/ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;cache/&quot;">​</a></h3><p>Stores downloaded remote spec files. Each file is cached with a SHA-256 hash of its URL as the filename:</p><ul><li><code>{hash}.spec</code> — the cached spec file content</li><li><code>{hash}.meta</code> — JSON metadata (source URL, cache time, TTL)</li></ul><p>Each cached file has a random TTL between 1 hour and 48 hours. The cache is automatically checked on every startup — if a valid (non-expired) entry exists, it is reused without downloading.</p><p><strong>Commands:</strong></p><ul><li><code>swag2mcp update</code> — clears cache and re-downloads all specs</li><li><code>swag2mcp clean</code> — clears cache and responses</li></ul><h3 id="specs" tabindex="-1">specs/ <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;specs/&quot;">​</a></h3><p>Stores local spec files that collections point to via <code>location: specs/{name}</code>. Files here are used directly without caching.</p><p>This directory is populated by:</p><ul><li><code>swag2mcp import &amp;lt;source&amp;gt; &amp;lt;name&amp;gt;</code> — downloads a remote spec and saves it here</li><li><code>swag2mcp export</code> — copies specs here into the export ZIP</li><li>Manual placement — you can copy spec files here yourself</li></ul><h3 id="responses" tabindex="-1">responses/ <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;responses/&quot;">​</a></h3><p>Stores API responses that exceed the <code>max_response_size</code> limit (default 1 MB). When the LLM invokes an endpoint and the response is too large, swag2mcp saves it here and returns a file reference instead.</p><p>Naming convention: <code>{domain}-{method}-{path_with_underscores}-{6char_hex}.json</code></p><p>Old responses are cleaned automatically after 48 hours on MCP server start.</p><h3 id="auth-scripts" tabindex="-1">auth_scripts/ <a class="header-anchor" href="#auth-scripts" aria-label="Permalink to &quot;auth_scripts/&quot;">​</a></h3><p>Stores authentication scripts for the <code>script</code> auth type. Each script is named after the spec&#39;s domain.</p><h4 id="naming-convention" tabindex="-1">Naming Convention <a class="header-anchor" href="#naming-convention" aria-label="Permalink to &quot;Naming Convention&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Platform</th><th>Filename</th><th>Example</th></tr></thead><tbody><tr><td>Unix (Linux, macOS)</td><td><code>{domain}.sh</code></td><td><code>meteo.sh</code></td></tr><tr><td>Windows</td><td><code>{domain}.bat</code></td><td><code>meteo.bat</code></td></tr></tbody></table><p>The domain must not contain <code>/</code> or <code>\\</code> characters.</p><h4 id="how-scripts-work" tabindex="-1">How Scripts Work <a class="header-anchor" href="#how-scripts-work" aria-label="Permalink to &quot;How Scripts Work&quot;">​</a></h4><ol><li>swag2mcp runs the script with a 30-second timeout</li><li>The script must output valid JSON to stdout</li><li>swag2mcp parses the JSON and uses the token for API requests</li></ol><h4 id="expected-output-format" tabindex="-1">Expected Output Format <a class="header-anchor" href="#expected-output-format" aria-label="Permalink to &quot;Expected Output Format&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-token-here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>✅</td><td>The authentication token</td></tr><tr><td><code>access_token</code></td><td>string</td><td>❌</td><td>Alternative to <code>token</code> (checked first)</td></tr><tr><td><code>token_type</code></td><td>string</td><td>❌</td><td>Token type (e.g., &quot;Bearer&quot;)</td></tr><tr><td><code>expires_in</code></td><td>number</td><td>❌</td><td>Token lifetime in seconds (default: 3600)</td></tr></tbody></table><h4 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Platform</th><th>Command</th></tr></thead><tbody><tr><td>Unix</td><td><code>sh {domain}.sh</code></td></tr><tr><td>Windows</td><td><code>cmd /c {domain}.bat</code></td></tr></tbody></table><h4 id="token-caching" tabindex="-1">Token Caching <a class="header-anchor" href="#token-caching" aria-label="Permalink to &quot;Token Caching&quot;">​</a></h4><p>The token is cached in memory until it expires. On each API call, swag2mcp checks the cache first — the script is only executed when the cached token has expired.</p><h4 id="stub-creation" tabindex="-1">Stub Creation <a class="header-anchor" href="#stub-creation" aria-label="Permalink to &quot;Stub Creation&quot;">​</a></h4><p>When you configure <code>auth: { type: script, config: { domain: &quot;myapi&quot; } }</code>, swag2mcp creates a stub script automatically:</p><p><strong>Unix (<code>auth_scripts/myapi.sh</code>):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;token&quot;: &quot;your-token-here&quot;, &quot;expires_in&quot;: 3600}&#39;</span></span></code></pre></div><p><strong>Windows (<code>auth_scripts/myapi.bat</code>):</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-token-here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 3600}</span></span></code></pre></div><p>Replace the placeholder token with your actual authentication logic.</p><h4 id="orphan-cleanup" tabindex="-1">Orphan Cleanup <a class="header-anchor" href="#orphan-cleanup" aria-label="Permalink to &quot;Orphan Cleanup&quot;">​</a></h4><p>When you delete a spec, its auth script becomes orphaned. swag2mcp automatically removes orphan scripts on:</p><ul><li><code>swag2mcp update</code></li><li><code>swag2mcp clean</code></li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><h3 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Validates the config, clears the cache and responses, then re-downloads all spec files. Also ensures auth scripts exist and removes orphan scripts.</p><p>Use this command after:</p><ul><li>Adding or removing collections</li><li>Changing collection locations</li><li>Editing spec files that need re-caching</li></ul><h3 id="clean" tabindex="-1">clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;clean&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Removes all contents of <code>cache/</code> and <code>responses/</code>, plus orphan auth scripts. Does NOT re-cache specs — use <code>update</code> for that.</p><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;validate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Validates the config including all collection locations. See <a href="./../cli/validate">CLI: validate</a>.</p><h2 id="export-and-import" tabindex="-1">Export and Import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to &quot;Export and Import&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export workspace to ZIP (default name: swag2mcp-backup-{date}.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export to a specific path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export only specific specs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restore from backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span></code></pre></div><p>Export includes: <code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>. Cache and responses are excluded (they are local data).</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p>If your workspace is inside a Git repository, add these entries to <code>.gitignore</code>:</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># swag2mcp — local data only</span></span>
<span class="line"><span>.swag2mcp/cache/</span></span>
<span class="line"><span>.swag2mcp/responses/</span></span></code></pre></div><p>The <code>cache/</code> and <code>responses/</code> directories contain local, machine-specific data that should not be committed. Everything else (<code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>) should be in the repository so the configuration is shared across the team.</p>`,66)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
